import java.util.Arrays;
import java.util.function.BiFunction;

class Solution {
    public int climbStairs(int n, int[] costs) {
        BiFunction<Integer, Integer, Integer> calc_cost = (from, to) -> {
            Double x = costs[to - 1] + Math.pow((to - from), 2);
            return x.intValue();
        };
        int[] dp = new int[n + 1];
        Arrays.fill(dp, 1, n + 1, Integer.MAX_VALUE);
        for (int step = 0; step < dp.length - 1; step++) {
            var currCost = dp[step];
            for (int nextStep = step + 1; nextStep <= step + 3 && nextStep < dp.length; nextStep++) {
                var stepCost = calc_cost.apply(step, nextStep);
                dp[nextStep] = Math.min(dp[nextStep], currCost + stepCost);
            }
        }

        return dp[n];
    }
}

class Solution {
    public int climbStairs(int n, int[] costs) {
        if (n == 1) return costs[0] + 1;
        var thirdStepBack = 0;
        var secondStepBack = costs[0] + 1;
        var firstStepBack = costs[1] + Math.min(secondStepBack + 1, 4);
        var result = firstStepBack;
        for (int step = 3; step <= n; step++) {
            var oneStep = firstStepBack + 1;
            var twoStep = secondStepBack + 4;
            var threeStep = thirdStepBack + 9;
            thirdStepBack = secondStepBack;
            secondStepBack = firstStepBack;
            firstStepBack = result = costs[step - 1] + Math.min(oneStep, Math.min(twoStep, threeStep));
        }

        return result;
    }
}

